// Desktop calls cross the WebView2 native bridge as named DLL operations.
if (window.chrome?.webview) {
  const pending = new Map();
  let nextBridgeId = 0;
  window.chrome.webview.addEventListener('message', event => {
    const result = event.data;
    const resolve = pending.get(result.id);
    if (!resolve) return;
    pending.delete(result.id);
    const binary = atob(result.body || '');
    const bytes = Uint8Array.from(binary, char => char.charCodeAt(0));
    const emptyBody = [204, 205, 304].includes(result.status);
    resolve(new Response(emptyBody ? null : bytes, { status: result.status, headers: result.headers }));
  });
  const nativeFetch = window.fetch.bind(window);
  function desktopOperation(url, method) {
    const path = new URL(url, location.href).pathname.replace(/^\/api\/?/, '').replace(/\/$/, '');
    const parts = path.split('/').filter(Boolean);
    const verb = method.toUpperCase();
    if (parts[0] === 'auth') return `auth.${parts[1]?.replaceAll('-', '.') || 'unknown'}`;
    if (parts[0] === 'users' && parts[1] === 'me') return verb === 'PUT' ? 'users.update' : 'users.me';
    if (parts[0] === 'tasks') return parts[1] ? `tasks.${verb === 'DELETE' ? 'delete' : 'update'}` : `tasks.${verb === 'POST' ? 'create' : 'list'}`;
    if (parts[0] === 'assistant') return `assistant.${parts[1] || 'unknown'}`;
    if (parts[0] === 'finance') return `finance.${parts.slice(1).join('.') || 'list'}`;
    if (parts[0] === 'fitness') return `fitness.${parts.slice(1).join('.') || 'list'}`;
    if (parts[0] === 'documents') return `documents.${parts.slice(1).join('.') || 'list'}`;
    if (parts[0] === 'career') return `career.${parts.slice(1).join('.') || 'list'}`;
    if (parts[0] === 'export') return 'export.create';
    if (parts[0] === 'health') return 'health';
    return 'unknown';
  }
  window.fetch = async (input, init = {}) => {
    const url = typeof input === 'string' ? input : input.url;
    if (!new URL(url, location.href).pathname.startsWith('/api/')) return nativeFetch(input, init);
    const request = new Request(input, init);
    const id = `bridge-${++nextBridgeId}`;
    const headers = Object.fromEntries(request.headers.entries());
    const route = new URL(url, location.href).pathname.replace(/^\/api\/?/, '').split('/').filter(Boolean);
    const message = { id, operation: desktopOperation(url, request.method), token: (headers.authorization || '').replace(/^Bearer\s+/i, ''), entityId: /^\d+$/.test(route[1] || '') ? Number(route[1]) : null };
    if (request.body && headers['content-type']?.startsWith('multipart/form-data')) {
      const form = await request.formData();
      message.data = {};
      for (const [name, value] of form.entries()) {
        message.data[name] = value instanceof File ? { fileName: value.name, contentType: value.type, data: await value.arrayBuffer() } : value;
      }
    } else if (request.body) {
      const body = await request.text();
      try { message.data = JSON.parse(body); } catch { message.data = {}; }
    }
    return new Promise((resolve, reject) => {
      pending.set(id, resolve);
      window.chrome.webview.postMessage(message);
      setTimeout(() => { if (pending.delete(id)) reject(new Error('The desktop backend did not respond.')); }, 120000);
    });
  };
}

