function expiryInfo(value){if(!value)return null;const exp=String(value).slice(0,10),today=localDate(),days=Math.round((new Date(`${exp}T00:00:00`)-new Date(`${today}T00:00:00`))/86400000);return {text:days<0?'Expired':days===0?'Expires today':`Expires ${new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(`${exp}T00:00:00`))}`,className:days<0?'expired':days<=30?'soon':''}}
function renderDocuments(){const list=$('#document-list');list.innerHTML='';$('#document-count').textContent=documents.length;$('#documents-empty').hidden=documents.length>0;for(const item of documents){const row=document.createElement('div');row.className='document-row';const symbol=document.createElement('span');symbol.className='document-symbol';symbol.textContent=item.fileName.split('.').pop().slice(0,4);const info=document.createElement('div');info.className='document-info';const title=document.createElement('strong');title.textContent=item.title;const details=document.createElement('small');details.textContent=`${item.fileName} · ${fileSize(item.sizeBytes)} · Added ${new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(new Date(item.uploadedAt))}`;info.append(title,details);const meta=document.createElement('div');meta.className='document-meta';const category=document.createElement('span');category.className='document-category';category.textContent=item.category;meta.append(category);const expiry=expiryInfo(item.expiresAt);if(expiry){const label=document.createElement('span');label.className=`expiry-label ${expiry.className}`;label.textContent=expiry.text;meta.append(label)}const actions=document.createElement('div');actions.className='document-actions';const download=document.createElement('button');download.textContent='Download';download.onclick=()=>downloadDocument(item);const edit=document.createElement('button');edit.textContent='Edit';edit.onclick=()=>editDocument(item);const del=document.createElement('button');del.className='delete-document';del.textContent='×';del.title='Delete document';del.onclick=async()=>{try{await api(`/documents/${item.id}`,{method:'DELETE'});await loadDocuments()}catch(err){toast(err.message)}};actions.append(download,edit,del);row.append(symbol,info,meta,actions);list.append(row)}}
