async function loadCareer(){if(!token)return;try{careerData=await api('/career');$('#career-app-count').textContent=careerData.applicationCount;$('#career-interview-count').textContent=careerData.interviewCount;$('#career-skill-count').textContent=careerData.skillCount;renderApplications();renderSkills()}catch(err){toast(err.message)}}
function renderApplications(){const items=careerData.applications.filter(x=>!$('#application-filter').value||x.status===$('#application-filter').value);const list=$('#application-list');list.innerHTML='';$('#application-total').textContent=items.length;$('#application-empty').hidden=items.length>0;for(const item of items){const row=document.createElement('div');row.className='career-row';const icon=document.createElement('span');icon.className=`career-symbol ${item.status}`;icon.textContent=({saved:'☆',applied:'↗',interview:'◷',offer:'✓',rejected:'—'})[item.status]||'↗';const info=document.createElement('div');info.className='career-info';const heading=document.createElement('strong');heading.textContent=`${item.role} · ${item.company}`;const detail=document.createElement('small');const next=item.nextStepAt?`Next step ${new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(item.nextStepAt))}`:item.appliedAt?`Applied ${new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(item.appliedAt))}`:'No dates added';detail.textContent=[item.status,next,item.notes].filter(Boolean).join(' · ');info.append(heading,detail);const actions=document.createElement('div');actions.className='career-actions';if(item.jobUrl){const link=document.createElement('a');link.href=item.jobUrl;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Job link';actions.append(link)}const edit=document.createElement('button');edit.textContent='Edit';edit.onclick=()=>openApplication(item);const del=document.createElement('button');del.className='delete';del.textContent='×';del.title='Delete application';del.onclick=async()=>{try{await api(`/career/applications/${item.id}`,{method:'DELETE'});await loadCareer()}catch(err){toast(err.message)}};actions.append(edit,del);row.append(icon,info,actions);list.append(row)}}
