$('#assistant-form').onsubmit=async e=>{e.preventDefault();const message=$('#assistant-message').value.trim();if(!message)return;$('#assistant-error').textContent='';const prior=assistantHistory.slice(-8);assistantHistory.push({role:'user',text:message});addChatMessage('user',message);$('#assistant-message').value='';$('#assistant-send').disabled=true;const pending=addChatMessage('assistant','Thinking…','pending');const context=Object.fromEntries([...document.querySelectorAll('[data-context]')].map(input=>[input.dataset.context,input.checked]));try{const result=await api('/assistant/chat',{method:'POST',body:JSON.stringify({message,history:prior,context})});pending.remove();assistantHistory.push({role:'assistant',text:result.reply});addChatMessage('assistant',result.reply)}catch(err){pending.remove();$('#assistant-error').textContent=err.message;if(err.message.includes('OPENAI_API_KEY')){$('#assistant-setup').hidden=false;$('#assistant-status').textContent='API key needed'}}finally{$('#assistant-send').disabled=false;$('#assistant-message').focus()}};

let currentTaskView='my-day',editingTask=null;
function render(){
  if(currentTaskView==='calendar'){renderCalendar();return}
  const today=localDate(), query=$('#task-search').value.trim().toLocaleLowerCase();
  const status=$('#task-status-filter').value, priority=$('#task-priority-filter').value, sort=$('#task-sort').value;
  const visible=tasks.filter(task=>{
    if(currentTaskView==='my-day'&&(task.status==='done'||!task.dueAt||String(task.dueAt).slice(0,10)>today))return false;
    if(status&&task.status!==status)return false;
    if(priority&&task.priority!==priority)return false;
    return !query||`${task.title} ${task.description||''}`.toLocaleLowerCase().includes(query);
  });
  const rank={high:0,normal:1,low:2};
  visible.sort((a,b)=>sort==='priority'?rank[a.priority]-rank[b.priority]:sort==='created'?new Date(b.createdAt)-new Date(a.createdAt):sort==='title'?a.title.localeCompare(b.title):((a.dueAt||'9999').localeCompare(b.dueAt||'9999')));
  $('#tasks-heading').childNodes[0].textContent=currentTaskView==='my-day'?'My day ':'All tasks ';
  $('#task-total').textContent=visible.length;
  $('#open-count').textContent=tasks.filter(t=>t.status==='open').length;
  $('#progress-count').textContent=tasks.filter(t=>t.status==='in-progress').length;
  $('#done-count').textContent=tasks.filter(t=>t.status==='done').length;
  const list=$('#task-list');list.innerHTML='';
  const originalTasks=tasks;tasks=visible;renderTaskRows();visible.forEach((task,index)=>{const meta=$('#task-list').children[index]?.querySelector('.task-meta');if(meta&&task.recurrence&&task.recurrence!=='none'){const repeat=document.createElement('span');repeat.textContent=`Repeats ${task.recurrence}`;meta.append(repeat)}if(meta&&task.reminderAt&&!task.reminderSentAt){const reminder=document.createElement('span');reminder.textContent='Reminder set';meta.append(reminder)}});tasks=originalTasks;
  const empty=$('#empty');empty.hidden=visible.length>0;
  empty.querySelector('strong').textContent=tasks.length===0?'A little space to start':'No tasks match this view';
  empty.querySelector('span').textContent=tasks.length===0?(currentTaskView==='my-day'?'Tasks due today or overdue will show up here.':'Create a task to get started.'):(currentTaskView==='my-day'?'Tasks due today or overdue will show up here.':'Try changing your search or filters.');
  $('#empty-add').hidden=tasks.length!==0;
}
function renderTaskRows(){
  const list=$('#task-list');
  for(const task of tasks){
    const row=document.createElement('div');row.className=`task-row ${task.status==='done'?'done':''}`;
    const check=document.createElement('button');check.className='check';check.setAttribute('aria-label',task.status==='done'?'Mark as to do':'Mark complete');check.textContent=task.status==='done'?'✓':'';check.onclick=()=>update(task,{status:task.status==='done'?'open':'done'});
    const text=document.createElement('div');text.className='task-text';const title=document.createElement('strong');title.textContent=task.title;text.append(title);
    const meta=document.createElement('div');meta.className='task-meta';if(task.description){const note=document.createElement('span');note.textContent=task.description;meta.append(note)}if(task.dueAt){const due=document.createElement('span');due.textContent=new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(task.dueAt));meta.append(due)}const badge=document.createElement('span');badge.className=`badge ${task.priority}`;badge.textContent=task.priority;meta.append(badge);text.append(meta);
    const status=document.createElement('select');status.className='status-select';status.setAttribute('aria-label','Task status');for(const [value,label] of [['open','To do'],['in-progress','In progress'],['done','Done']]){const option=document.createElement('option');option.value=value;option.textContent=label;option.selected=task.status===value;status.append(option)}status.onchange=()=>update(task,{status:status.value});
    const edit=document.createElement('button');edit.className='task-edit';edit.type='button';edit.textContent='Edit';edit.onclick=()=>openTask(task);
    const del=document.createElement('button');del.className='delete';del.textContent='×';del.title='Delete task';del.setAttribute('aria-label',`Delete ${task.title}`);del.onclick=async()=>{if(!confirm(`Delete “${task.title}”?`))return;try{await api(`/tasks/${task.id}`,{method:'DELETE'});await loadTasks()}catch(err){toast(err.message)}};
    row.append(check,text,status,edit,del);list.append(row);
  }
}
for(const selector of ['#task-search','#task-status-filter','#task-priority-filter','#task-sort'])$(selector).addEventListener(selector==='#task-search'?'input':'change',render);
function setView(view){
  currentTaskView=view==='calendar'?'calendar':view==='all-tasks'?'all-tasks':'my-day';
  const taskView=view==='my-day'||view==='all-tasks'||view==='tasks',calendar=view==='calendar',finance=view==='finance',fitness=view==='fitness',documents=view==='documents',career=view==='career',assistantView=view==='assistant',settings=view==='settings';
  $('#tasks-view').hidden=!(taskView||view==='tasks');$('#calendar-view').hidden=!calendar;$('#finance-view').hidden=!finance;$('#fitness-view').hidden=!fitness;$('#documents-view').hidden=!documents;$('#career-view').hidden=!career;$('#assistant-view').hidden=!assistantView;$('#settings-view').hidden=!settings;
  $('#page-title').textContent=calendar?'Calendar':taskView?(currentTaskView==='my-day'?'My day':'All tasks'):finance?'Finance':fitness?'Fitness':documents?'Documents':career?'Career':assistantView?'AI assistant':'Settings';
  document.querySelectorAll('.nav-item').forEach(link=>link.classList.toggle('active',link.dataset.view===view));$('#task-tools').hidden=currentTaskView!=='all-tasks';
  if(taskView||calendar)render();if(finance)loadFinance();if(fitness)loadFitness();if(documents)loadDocuments();if(career)loadCareer();if(assistantView)loadAssistantStatus();if(settings)loadSettings();
}
const calendarMonth=$('#calendar-month');calendarMonth.value=localDate().slice(0,7);calendarMonth.onchange=renderCalendar;
$('#calendar-prev').onclick=()=>shiftCalendarMonth(-1);$('#calendar-next').onclick=()=>shiftCalendarMonth(1);$('#calendar-today').onclick=()=>{calendarMonth.value=localDate().slice(0,7);renderCalendar()};
function shiftCalendarMonth(offset){const [year,month]=calendarMonth.value.split('-').map(Number);const date=new Date(year,month-1+offset,1);calendarMonth.value=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;renderCalendar()}
function renderCalendar(){if(!calendarMonth)return;const [year,month]=calendarMonth.value.split('-').map(Number);if(!year||!month)return;const grid=$('#calendar-grid');grid.replaceChildren();for(const name of ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']){const head=document.createElement('div');head.className='calendar-weekday';head.textContent=name;head.setAttribute('role','columnheader');grid.append(head)}const firstDay=new Date(year,month-1,1).getDay(),days=new Date(year,month,0).getDate();for(let i=0;i<firstDay;i++){const blank=document.createElement('div');blank.className='calendar-cell calendar-blank';blank.setAttribute('role','gridcell');grid.append(blank)}for(let day=1;day<=days;day++){const date=`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const cell=document.createElement('div');cell.className=`calendar-cell${date===localDate()?' today-cell':''}`;cell.setAttribute('role','gridcell');const number=document.createElement('strong');number.textContent=day;cell.append(number);const dayTasks=tasks.filter(task=>task.dueAt&&String(task.dueAt).slice(0,10)===date);for(const task of dayTasks.slice(0,3)){const item=document.createElement('div');item.className=`calendar-task ${task.status==='done'?'complete':''}`;item.textContent=task.title;item.title=task.title;cell.append(item)}if(dayTasks.length>3){const more=document.createElement('small');more.textContent=`+${dayTasks.length-3} more`;cell.append(more)}grid.append(cell)}}
