$('#download-backup').onclick=async()=>{const button=$('#download-backup');button.disabled=true;$('#backup-error').textContent='';try{const response=await fetch('/api/export',{headers:{Authorization:`Bearer ${token}`}});if(response.status===401&&token){localStorage.removeItem(tokenKey);token=null;showAuth();throw Error('Please sign in again.')}if(!response.ok){let message='Could not create the backup.';try{message=(await response.json()).message||message}catch{}throw Error(message)}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`lifeos-backup-${localDate()}.zip`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded.')}catch(err){$('#backup-error').textContent=err.message}finally{button.disabled=false}};
const financeRenderer=renderFinance;
renderFinance=function(data){financeRenderer(data);const totals=new Map();for(const item of transactions)if(item.type==='expense')totals.set(item.category,(totals.get(item.category)||0)+item.amountMinor);const categories=[...totals].sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...categories.map(x=>x[1]));$('#category-report').hidden=categories.length===0;$('#category-bars').replaceChildren(...categories.map(([name,value])=>{const row=document.createElement('div');row.className='category-row';const label=document.createElement('span');label.textContent=name;const track=document.createElement('div');track.className='category-track';const fill=document.createElement('span');fill.style.width=`${Math.max(3,Math.round(value/max*100))}%`;track.append(fill);const amount=document.createElement('strong');amount.textContent=money(value);row.append(label,track,amount);return row}))};
$('#export-finance').onclick=()=>{const safe=value=>{const text=String(value??'');return `"${(/^[=+\-@\t\r]/.test(text)?"'":"")}${text.replaceAll('"','""')}"`};const rows=[['Date','Type','Category','Amount INR','Note'],...transactions.map(x=>[String(x.occurredAt).slice(0,10),x.type,x.category,(x.amountMinor/100).toFixed(2),x.note||''])];const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`lifeos-finance-${monthInput.value}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)};
function openTask(task=null){editingTask=task;$('#task-form').hidden=false;$('#task-title').value=task?.title||'';$('#task-description').value=task?.description||'';$('#task-priority').value=task?.priority||'normal';$('#task-due').value=task?.dueAt?String(task.dueAt).slice(0,10):'';$('#task-recurrence').value=task?.recurrence||'none';$('#task-reminder').value=task?.reminderAt?new Date(new Date(task.reminderAt).getTime()-new Date(task.reminderAt).getTimezoneOffset()*60000).toISOString().slice(0,16):'';$('#task-form').querySelector('button[type="submit"]').textContent=task?'Save task':'Add task';$('#task-title').focus()}
