$('#task-form').onsubmit=async e=>{e.preventDefault();const title=$('#task-title').value.trim();if(!title)return;const reminder=$('#task-reminder').value;const body={title,description:$('#task-description').value||null,status:editingTask?.status||'open',priority:$('#task-priority').value,dueAt:$('#task-due').value?new Date(`${$('#task-due').value}T12:00:00`).toISOString():null,recurrence:$('#task-recurrence').value,reminderAt:reminder?new Date(reminder).toISOString():null};try{await api(editingTask?`/tasks/${editingTask.id}`:'/tasks',{method:editingTask?'PUT':'POST',body:JSON.stringify(body)});e.target.reset();e.target.hidden=true;editingTask=null;await loadTasks();toast('Task saved.')}catch(err){toast(err.message)}};
const chartedFinanceRenderer=renderFinance;
renderFinance=function(data){chartedFinanceRenderer(data);const list=$('#budget-list');list.replaceChildren();const budgets=data.budgets||[];$('#budget-empty').hidden=budgets.length>0;for(const budget of budgets){const spent=data.categorySpending?.[budget.category]||0,ratio=budget.amountMinor?spent/budget.amountMinor:0;const row=document.createElement('div');row.className=`budget-row${ratio>1?' over-budget':''}`;const heading=document.createElement('div');heading.className='budget-heading';const name=document.createElement('strong');name.textContent=budget.category;const amounts=document.createElement('span');amounts.textContent=`${money(spent)} of ${money(budget.amountMinor)}`;heading.append(name,amounts);const track=document.createElement('div');track.className='budget-track';const fill=document.createElement('span');fill.style.width=`${Math.min(100,Math.round(ratio*100))}%`;track.append(fill);const remove=document.createElement('button');remove.type='button';remove.className='budget-delete';remove.textContent='Remove';remove.onclick=async()=>{try{await api(`/finance/budgets/${budget.id}`,{method:'DELETE'});await loadFinance()}catch(err){toast(err.message)}};row.append(heading,track,remove);list.append(row)}};
$('#budget-form').onsubmit=async e=>{e.preventDefault();$('#budget-error').textContent='';try{await api('/finance/budgets',{method:'POST',body:JSON.stringify({month:monthInput.value,category:$('#budget-category').value.trim(),amount:Number($('#budget-amount').value)})});e.target.reset();await loadFinance();toast('Monthly budget saved.')}catch(err){$('#budget-error').textContent=err.message}};
if(token&&user){showApp();const initial=location.hash.slice(1);setView(['my-day','all-tasks','calendar','finance','fitness','documents','career','assistant','settings'].includes(initial)?initial:'my-day')}else showAuth();
